// === Tab: Block ===
class Block {
	constructor(pos, tpos) {
		this.pos = pos;
		this.tpos = tpos;
		this.wilt = 1.2;
		this.erode = 0;
	}
	show() {
		this.pos.lerp(this.tpos, 0.1);
		if (this.wilt > wilt) this.wilt = wilt;
		if (this.erode < erode) this.erode = erode;
		push();
		fill(255);
		specularMaterial(255);
		noStroke();
		translate(this.pos);
		translate(0, -dim / 8 + (1.2 - this.wilt) * dim / 2, 0);
		scale(2 - this.wilt, this.wilt, 2 - this.wilt);
		box(dim - this.erode, dim - this.erode, dim);
		box(dim - this.erode, dim, dim - this.erode);
		box(dim, dim - this.erode, dim - this.erode);
		for (let ay = 0; ay < TAU; ay += (Math.max(0.001, Math.abs(HALF_PI)) || 1)) {
			push();
			rotateY(ay + QUARTER_PI);
			translate((dim - this.erode) * sqrt(2) / 2, 0, 0);
			cylinder(this.erode / 2, dim - this.erode, 72, 1);
			pop();
		}
		rotateZ(HALF_PI);
		for (let ay = 0; ay < TAU; ay += (Math.max(0.001, Math.abs(HALF_PI)) || 1)) {
			push();
			rotateY(ay + QUARTER_PI);
			translate((dim - this.erode) * sqrt(2) / 2, 0, 0);
			cylinder(this.erode / 2, dim - this.erode, 72, 1);
			pop();
		}
		rotateX(HALF_PI);
		for (let ay = 0; ay < TAU; ay += (Math.max(0.001, Math.abs(HALF_PI)) || 1)) {
			push();
			rotateY(ay + QUARTER_PI);
			translate((dim - this.erode) * sqrt(2) / 2, 0, 0);
			cylinder(this.erode / 2, dim - this.erode, 72, 1);
			translate(0, (dim - this.erode) / 2, 0);
			sphere(this.erode / 2, 36, 36);
			translate(0, -(dim - this.erode), 0);
			sphere(this.erode / 2, 36, 36);
			pop();
		}
		pop();
		if (this.wilt < 0.1) {
			push();
			fill(255);
			specularMaterial(255);
			translate(this.pos);
			translate(0, -dim / 8 + (1.2 - this.wilt) * dim / 2, 0);
			scale(2 - this.wilt, 2, 2 - this.wilt);
			rotateX(HALF_PI);
			torus(dim / 2 + (0.1 - this.wilt) * dim / 8, (0.1 - this.wilt) * dim / 4, 72, 16);
			if (mode == 1) {
				rotateX(-HALF_PI);
				translate(0, -(0.1 - this.wilt) * dim / 4, 0);
				cylinder(dim / 4, (0.1 - this.wilt) * dim / 4, 72, 1);
			}
			pop();
		}
	}
}

function makeDie() {
	noStroke();
	fill(50, 180);
	specularMaterial(255);
	die = csg(() => cylinder(dim, dim / 8, 72, 1)).subtract(() => {
		translate(0, dim / 8, 0);
		cylinder(dim / 2, dim / 4, 72, 1);
	}).done();
}

// === Tab: mySketch ===
// For the #WCCChallenge, theme: "pressure."
// Alternative working titles: "waffle maker," "tortilla press," and "s'mores factory"! :)

let dim, erode, wilt, spin, tilt, clamp;
let blocks = [];
let die;
let mode = 0;
let tilting = true;

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	dim = 200;
	erode = 0;
	wilt = 1.2;
	spin = 0;
	tilt = 0;
	clamp = 1;
	makeDie();
	pos = createVector(0, 0, 0);
	tpos = createVector(0, 0, 0);
	blocks.push(new Block(pos, tpos));
}

function draw() {
	if (frameCount > 60) {
		erode = lerp(erode, map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), height / 8, 7 * height / 8, 0, dim, true), 0.1);
		wilt = lerp(wilt, map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), height / 8, 7 * height / 8, 1.2, 0.01, true), 0.1);
		clamp = lerp(clamp, map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), height / 8, 7 * height / 8, 1.2, 0.01, true), 0.1);
	} else {
		erode = 0;
		wilt = 1.2;
		clamp = lerp(clamp, 1.2, 0.2);
	}
	spin = lerp(spin, map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), width / 8, 7 * width / 8, -QUARTER_PI, QUARTER_PI, true), 0.1);
	if(tilting) tilt = lerp(tilt, map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), height / 8, 7 * height / 8, PI / 18, -PI / 18, true), 0.1);
	else tilt = lerp(tilt, PI/18, 0.1);
	orbitControl(0, 0, -1);
	rotateX(-PI / 12 + tilt);
	rotateY(spin);
	background(0);
	ambientLight(120, 120, 120);
	pointLight(120, 120, 120, height / 2, -height, height);
	specularMaterial(255);
	shininess(2);
	metalness(2);
	noStroke();
	for (let b of blocks) {
		b.show();
	}
	push();
	fill(50, 180);
	translate(0, (dim / 2) - (clamp * dim) - dim / 12, 0);
	if(mode==0) cylinder(dim, dim / 8, 72, 1);
	else model(die);
	pop();
	push();
	fill(50, 180);
	translate(0, (dim / 2) + dim / 16, 0);
	cylinder(dim, dim / 8, 72, 1);
	pop();
}

function mouseClicked() {
	frameCount = 0;
	blocks[0].tpos.y = (-dim / 2) * (1.2 - blocks[0].wilt);
	setTimeout(makeNew, 200);
}

function makeNew() {
	blocks[0].tpos.x = 2 * width;
	let pos = createVector(-2 * width, 0, 0);
	let tpos = createVector(0, 0, 0);
	blocks.push(new Block(pos, tpos));
	setTimeout(destroyLast, 500);
}



function destroyLast() {
	blocks.splice(0, 1);
}

function keyPressed(){
	if(keyCode==13) mode=1-mode;
	if(keyCode==32) tilting=!tilting;
}
